/**
 * field-status resolver tests (MOR-429).
 *
 * Covers parent/child availability resolution and — crucially — anchors the
 * frontend public-path keys to a REAL backend-emitted `field_status` payload.
 * The golden fixture `fixtures/empty-store-field-status.json` is generated by
 * `scripts/gen_field_status_fixture.py` from the backend public-state
 * projection of an empty StateStore, and guarded read-only by
 * `tests/test_field_status_frontend_fixture.py`. Importing it here proves the
 * keys the toolbar/LCD gate on (`scopeControls.mode`, `main.agc`, …) actually
 * match the keys the backend emits and resolve to unavailable.
 */
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import type { ServerState } from '$lib/types/state';
import { setLocale } from '$lib/i18n';
import { _resetLocale } from '$lib/i18n/store.svelte';
import {
  getFieldAvailability,
  getFieldAvailabilityMessage,
  isFieldAvailable,
  areFieldsAvailable,
  resolveFieldStatusMessage,
  refusedFieldEntries,
} from '../field-status';
import emptyStoreFieldStatus from './fixtures/empty-store-field-status.json';

function stateWith(fieldStatus: Record<string, unknown>): ServerState {
  return { fieldStatus } as unknown as ServerState;
}

describe('field-status parent/child resolution', () => {
  it('uses the same nearest ancestor for availability and its explanation', () => {
    const state = stateWith({
      scopeControls: { observed: false, freshness: 'unknown', availability: 'unavailable', message: 'Outer refusal' },
      'scopeControls.group': { observed: false, freshness: 'unknown', availability: 'unavailable', message: 'Nearest refusal' },
      'scopeControls.group.mode': { observed: true, freshness: 'fresh', availability: 'available', message: 'Obsolete leaf message' },
    });
    expect(getFieldAvailability(state, 'scopeControls.group.mode')).toBe('unavailable');
    expect(getFieldAvailabilityMessage(state, 'scopeControls.group.mode')).toBe('Nearest refusal');
    expect(getFieldAvailabilityMessage(state, 'scopeControls.group.edge')).toBe('Nearest refusal');
    expect(getFieldAvailabilityMessage(state, 'main.mode')).toBeUndefined();
  });

  it('keeps own refusal precedence and does not expose messages on held stale readings', () => {
    const state = stateWith({
      main: { observed: false, freshness: 'unknown', availability: 'unavailable', message: 'Parent refusal' },
      'main.nr': { observed: false, freshness: 'unknown', availability: 'unavailable', message: 'Own refusal' },
      'main.nb': { observed: true, freshness: 'stale', availability: 'stale', message: 'Old refusal' },
    });
    expect(getFieldAvailabilityMessage(state, 'main.nr')).toBe('Own refusal');
    expect(getFieldAvailabilityMessage(state, 'main.nb')).toBeUndefined();
    expect(getFieldAvailabilityMessage(null, 'main.nr')).toBeUndefined();
  });
  it('treats a leaf as available when no entry and no ancestor entry exist', () => {
    const state = stateWith({
      'main.freqHz': { availability: 'available', freshness: 'fresh', observed: true },
    });
    expect(getFieldAvailability(state, 'scopeControls.mode')).toBe('available');
  });

  it('inherits a missing parent when the child has no own entry', () => {
    const state = stateWith({
      scopeControls: { availability: 'missing', freshness: 'unknown', observed: false },
    });
    expect(getFieldAvailability(state, 'scopeControls.mode')).toBe('missing');
    expect(isFieldAvailable(state, 'scopeControls.span')).toBe(false);
  });

  it('inherits a stale-but-observed parent as available when the child has no own entry (MOR-2425/R29)', () => {
    const state = stateWith({
      scopeControls: { availability: 'stale', freshness: 'stale', observed: true },
    });
    expect(getFieldAvailability(state, 'scopeControls.refDb')).toBe('available');
  });

  it('lets a missing parent override a child that claims available', () => {
    const state = stateWith({
      scopeControls: { availability: 'missing', freshness: 'unknown', observed: false },
      'scopeControls.span': { availability: 'available', freshness: 'fresh', observed: true },
    });
    // The group is unobserved as a whole — a leaf inheriting from a missing
    // parent must not be confirmed even if it carries an `available` own entry.
    expect(getFieldAvailability(state, 'scopeControls.span')).toBe('missing');
  });

  it('treats an own stale-but-observed entry as available regardless of parent (MOR-2425/R29)', () => {
    const state = stateWith({
      'scopeControls.span': { availability: 'stale', freshness: 'stale', observed: true },
    });
    expect(getFieldAvailability(state, 'scopeControls.span')).toBe('available');
    expect(isFieldAvailable(state, 'scopeControls.span')).toBe(true);
  });

  // MOR-2425/T201: the backend now distinguishes `unavailable` (declared,
  // absent in this state) and `undeclared` (not declared for this radio)
  // from `missing`. Neither is a reading, so neither may pass as available.
  it.each(['unavailable', 'undeclared'] as const)(
    'does not treat %s as an available reading',
    (availability) => {
      const state = stateWith({
        'global.powerMeter': { availability, freshness: 'unknown', observed: false },
      });
      expect(getFieldAvailability(state, 'global.powerMeter')).toBe(availability);
      expect(isFieldAvailable(state, 'global.powerMeter')).toBe(false);
      expect(areFieldsAvailable(state, ['global.powerMeter'])).toBe(false);
      // A child with no own entry inherits it, and is not available either.
      expect(isFieldAvailable(state, 'global.powerMeter.value')).toBe(false);
    },
  );
});

describe('field-status anchored to the real backend payload', () => {
  const state = stateWith(emptyStoreFieldStatus as Record<string, unknown>);

  const toolbarScopeKeys = [
    'scopeControls.mode',
    'scopeControls.edge',
    'scopeControls.span',
    'scopeControls.speed',
    'scopeControls.hold',
    'scopeControls.refDb',
    'scopeControls.dual',
    'scopeControls.receiver',
  ];

  const backendKeys = Object.keys(emptyStoreFieldStatus as Record<string, unknown>);

  it('emits the scope-control leaves the toolbar gates on', () => {
    for (const key of toolbarScopeKeys) {
      expect(backendKeys, `backend must emit ${key}`).toContain(key);
    }
  });

  it('resolves every scope-control leaf to unavailable for an empty store', () => {
    expect(areFieldsAvailable(state, toolbarScopeKeys)).toBe(false);
    for (const key of toolbarScopeKeys) {
      expect(isFieldAvailable(state, key), `${key} should be unavailable`).toBe(false);
    }
  });

  it('resolves per-receiver LCD indicators (agc/preamp/att/…) to unavailable', () => {
    for (const key of ['main.agc', 'main.preamp', 'main.att', 'main.nb', 'main.nr', 'main.rfGain', 'main.squelch']) {
      expect(backendKeys, `backend must emit ${key}`).toContain(key);
      expect(isFieldAvailable(state, key), `${key} should be unavailable`).toBe(false);
    }
  });
});

describe('field-status refusal localisation (MOR-4828)', () => {
  beforeEach(() => {
    localStorage.clear();
    _resetLocale();
    setLocale('en-US');
  });

  afterEach(() => {
    localStorage.clear();
    _resetLocale();
  });

  const EN_REFUSED =
    'The radio refused to report mic gain. The control is unavailable ' +
    'until the radio answers. The app is still connected.';
  const RU_REFUSED =
    'Радио отказалось сообщить mic gain. Элемент управления недоступен, ' +
    'пока радио не ответит. Приложение остаётся на связи.';
  const JA_REFUSED =
    'トランシーバーがmic gainの報告を拒否しました。このコントロールは' +
    'トランシーバーが応答するまで利用できません。アプリは接続を維持しています。';

  const refusedRow = (overrides: Record<string, unknown> = {}) => ({
    storePath: 'global.operator_controls.mic_gain',
    observed: false,
    freshness: 'unknown',
    availability: 'unavailable',
    message: EN_REFUSED,
    messageKey: 'readRefused',
    messageParams: { field: 'mic gain' },
    ...overrides,
  });

  it('renders the keyed refusal sentence in en-US, byte-identical to the wire fallback', () => {
    const state = stateWith({ micGain: refusedRow() });
    expect(resolveFieldStatusMessage(state.fieldStatus?.['micGain'])).toBe(EN_REFUSED);
    expect(getFieldAvailabilityMessage(state, 'micGain')).toBe(EN_REFUSED);
  });

  it('renders the keyed refusal sentence in ru-RU', () => {
    setLocale('ru-RU');
    const state = stateWith({ micGain: refusedRow() });
    expect(resolveFieldStatusMessage(state.fieldStatus?.['micGain'])).toBe(RU_REFUSED);
  });

  it('renders the keyed refusal sentence in ja-JP', () => {
    setLocale('ja-JP');
    const state = stateWith({ micGain: refusedRow() });
    expect(resolveFieldStatusMessage(state.fieldStatus?.['micGain'])).toBe(JA_REFUSED);
  });

  it('renders the malformed variant through its own key', () => {
    const state = stateWith({
      micGain: refusedRow({
        message: 'The radio returned an invalid reply for mic gain. The control is unavailable until the radio answers. The app is still connected.',
        messageKey: 'readMalformed',
      }),
    });
    expect(getFieldAvailabilityMessage(state, 'micGain')).toBe(
      'The radio returned an invalid reply for mic gain. The control is unavailable until the radio answers. The app is still connected.',
    );
  });

  it('falls back to the English message when the key is unknown', () => {
    const state = stateWith({ micGain: refusedRow({ messageKey: 'notARealCode' }) });
    expect(resolveFieldStatusMessage(state.fieldStatus?.['micGain'])).toBe(EN_REFUSED);
  });

  it('falls back to the English message when the key is missing (old sender)', () => {
    const { messageKey: _key, messageParams: _params, ...legacy } = refusedRow();
    const state = stateWith({ micGain: legacy });
    expect(resolveFieldStatusMessage(state.fieldStatus?.['micGain'])).toBe(EN_REFUSED);
    expect(refusedFieldEntries(state)).toHaveLength(1);
  });

  it('dedups public-path aliases of one store path into a single entry', () => {
    const state = stateWith({ micGain: refusedRow(), micGainAlias: refusedRow() });
    const entries = refusedFieldEntries(state);
    expect(entries).toHaveLength(1);
    expect(entries[0]).toEqual({
      storePath: 'global.operator_controls.mic_gain',
      publicPath: 'micGain',
      text: EN_REFUSED,
    });
  });

  it('ignores available rows and rows without a resolvable sentence', () => {
    const state = stateWith({
      micGain: refusedRow(),
      powerMeter: {
        storePath: 'global.meters.power',
        observed: false,
        freshness: 'unknown',
        availability: 'unavailable',
      },
      mainMode: {
        storePath: 'receiver.main.active.freq_mode.mode',
        observed: true,
        freshness: 'fresh',
        availability: 'available',
        message: 'Obsolete leaf message',
      },
    });
    expect(refusedFieldEntries(state).map((entry) => entry.publicPath)).toEqual(['micGain']);
  });

  it('returns no entries without state', () => {
    expect(refusedFieldEntries(null)).toEqual([]);
  });
});
